--
-- Name: v_admin_kpis; Type: VIEW; Schema: public; Owner: goacreator
--

CREATE VIEW public.v_admin_kpis AS
 SELECT ( SELECT (count(*))::integer AS count
           FROM public.users) AS total_users,
    ( SELECT (count(*))::integer AS count
           FROM public.creators) AS total_creators,
    ( SELECT (count(*))::integer AS count
           FROM public.businesses) AS total_businesses,
    ( SELECT (count(*))::integer AS count
           FROM public.users
          WHERE (users.is_verified = true)) AS verified_users,
    ( SELECT (count(*))::integer AS count
           FROM public.collaboration_requests
          WHERE (collaboration_requests.status = 'pending'::text)) AS pending_requests,
    ( SELECT (count(*))::integer AS count
           FROM public.collaboration_requests
          WHERE (collaboration_requests.status = 'accepted'::text)) AS active_collaborations,
    ( SELECT (count(*))::integer AS count
           FROM public.collaboration_requests
          WHERE (collaboration_requests.status = 'completed'::text)) AS completed_collaborations,
    ( SELECT COALESCE(sum(collaboration_requests.offered_amount), (0)::bigint) AS "coalesce"
           FROM public.collaboration_requests
          WHERE ((collaboration_requests.status = 'completed'::text) AND (collaboration_requests.collab_type = ANY (ARRAY['paid'::text, 'hybrid'::text])))) AS total_completed_deal_volume,
    ( SELECT round(avg(reviews.rating), 2) AS round
           FROM public.reviews) AS platform_avg_rating,
    ( SELECT (count(*))::integer AS count
           FROM public.audit_log) AS total_audit_entries;


ALTER VIEW public.v_admin_kpis OWNER TO goacreator;

--
-- Name: v_category_distribution; Type: VIEW; Schema: public; Owner: goacreator
--

CREATE VIEW public.v_category_distribution AS
 SELECT c.category_id,
    c.category_name,
    (count(cc.creator_id))::integer AS creator_count,
    (count(
        CASE
            WHEN cc.is_primary THEN 1
            ELSE NULL::integer
        END))::integer AS primary_creator_count,
    round((((count(cc.creator_id))::numeric * 100.0) / (NULLIF(( SELECT count(*) AS count
           FROM public.creators), 0))::numeric), 2) AS pct_of_creators
   FROM (public.categories c
     LEFT JOIN public.creator_categories cc ON ((c.category_id = cc.category_id)))
  GROUP BY c.category_id, c.category_name
  ORDER BY ((count(cc.creator_id))::integer) DESC;


ALTER VIEW public.v_category_distribution OWNER TO goacreator;

--
-- Name: v_collaborations; Type: VIEW; Schema: public; Owner: goacreator
--

CREATE VIEW public.v_collaborations AS
 SELECT cr.request_id,
    cr.business_id,
    b.business_name,
    cr.creator_id,
    c.full_name AS creator_name,
    bl.area_name AS business_area,
    bl.taluka AS business_taluka,
    cl.area_name AS creator_area,
    cl.taluka AS creator_taluka,
    cr.collab_type,
    cr.offered_amount,
    cr.offer_details,
    cr.deliverables,
    cr.message,
    cr.status,
    cr.requested_at,
    cr.responded_at,
    cr.deadline
   FROM ((((public.collaboration_requests cr
     JOIN public.businesses b ON ((cr.business_id = b.business_id)))
     JOIN public.locations bl ON ((b.location_id = bl.location_id)))
     JOIN public.creators c ON ((cr.creator_id = c.creator_id)))
     JOIN public.locations cl ON ((c.location_id = cl.location_id)))
  WHERE (cr.status = ANY (ARRAY['accepted'::text, 'completed'::text]));


ALTER VIEW public.v_collaborations OWNER TO goacreator;

--
-- Name: v_creator_latest_metrics; Type: VIEW; Schema: public; Owner: goacreator
--

CREATE VIEW public.v_creator_latest_metrics AS
 SELECT DISTINCT ON (account_id) metric_id,
    account_id,
    follower_count,
    avg_likes,
    avg_views,
    avg_comments,
    engagement_rate,
    audience_goa_pct,
    data_source,
    verified_by,
    recorded_at
   FROM public.creator_metrics
  ORDER BY account_id, recorded_at DESC;


ALTER VIEW public.v_creator_latest_metrics OWNER TO goacreator;

--
-- Name: v_creator_cards; Type: VIEW; Schema: public; Owner: goacreator
--

CREATE VIEW public.v_creator_cards AS
 WITH creator_cats AS (
         SELECT cc_1.creator_id,
            jsonb_agg(jsonb_build_object('category_id', c.category_id, 'category_name', c.category_name, 'is_primary', cc_1.is_primary) ORDER BY cc_1.is_primary DESC, c.category_name) AS categories,
            max(
                CASE
                    WHEN cc_1.is_primary THEN c.category_name
                    ELSE NULL::text
                END) AS primary_category
           FROM (public.creator_categories cc_1
             JOIN public.categories c ON ((cc_1.category_id = c.category_id)))
          GROUP BY cc_1.creator_id
        ), creator_metrics_agg AS (
         SELECT sa.creator_id,
            (COALESCE(sum(lm.follower_count), (0)::bigint))::integer AS total_followers,
            round(COALESCE(avg(lm.engagement_rate), (0)::numeric), 2) AS avg_engagement_rate,
            bool_or((lm.data_source = 'admin_verified'::text)) AS has_admin_verified_metrics
           FROM (public.social_accounts sa
             LEFT JOIN public.v_creator_latest_metrics lm ON ((sa.account_id = lm.account_id)))
          GROUP BY sa.creator_id
        ), creator_reviews_agg AS (
         SELECT r.reviewee_id,
            round(avg(r.rating), 2) AS avg_rating,
            (count(r.review_id))::integer AS review_count
           FROM public.reviews r
          GROUP BY r.reviewee_id
        )
 SELECT cr.creator_id,
    cr.user_id,
    u.email,
    cr.full_name,
    cr.bio,
    cr.accepts_barter,
    cr.min_paid_rate,
    cr.created_at,
    l.location_id,
    l.area_name,
    l.taluka,
    l.district,
    COALESCE(cc.categories, '[]'::jsonb) AS categories,
    cc.primary_category,
    COALESCE(cma.total_followers, 0) AS total_followers,
    COALESCE(cma.avg_engagement_rate, (0)::numeric) AS avg_engagement_rate,
    COALESCE(cra.avg_rating, (0)::numeric) AS avg_rating,
    COALESCE(cra.review_count, 0) AS review_count,
    u.is_verified AS is_account_verified,
    COALESCE(cma.has_admin_verified_metrics, false) AS is_metrics_verified,
    (u.is_verified OR COALESCE(cma.has_admin_verified_metrics, false)) AS is_verified
   FROM (((((public.creators cr
     JOIN public.users u ON ((cr.user_id = u.user_id)))
     JOIN public.locations l ON ((cr.location_id = l.location_id)))
     LEFT JOIN creator_cats cc ON ((cr.creator_id = cc.creator_id)))
     LEFT JOIN creator_metrics_agg cma ON ((cr.creator_id = cma.creator_id)))
     LEFT JOIN creator_reviews_agg cra ON ((cr.user_id = cra.reviewee_id)));


ALTER VIEW public.v_creator_cards OWNER TO goacreator;

--
-- Name: v_monthly_request_velocity; Type: VIEW; Schema: public; Owner: goacreator
--

CREATE VIEW public.v_monthly_request_velocity AS
 SELECT to_char(date_trunc('month'::text, requested_at), 'YYYY-MM'::text) AS month,
    (count(*))::integer AS total_requests,
    (count(
        CASE
            WHEN (status = 'pending'::text) THEN 1
            ELSE NULL::integer
        END))::integer AS pending_count,
    (count(
        CASE
            WHEN (status = 'accepted'::text) THEN 1
            ELSE NULL::integer
        END))::integer AS accepted_count,
    (count(
        CASE
            WHEN (status = 'completed'::text) THEN 1
            ELSE NULL::integer
        END))::integer AS completed_count,
    (count(
        CASE
            WHEN (status = 'rejected'::text) THEN 1
            ELSE NULL::integer
        END))::integer AS rejected_count,
    (count(
        CASE
            WHEN (status = 'cancelled'::text) THEN 1
            ELSE NULL::integer
        END))::integer AS cancelled_count,
    COALESCE(sum(offered_amount), (0)::bigint) AS total_offered_amount,
    COALESCE(sum(
        CASE
            WHEN (status = 'completed'::text) THEN offered_amount
            ELSE 0
        END), (0)::bigint) AS completed_offered_amount
   FROM public.collaboration_requests
  GROUP BY (date_trunc('month'::text, requested_at))
  ORDER BY (date_trunc('month'::text, requested_at)) DESC;


ALTER VIEW public.v_monthly_request_velocity OWNER TO goacreator;

--
-- Name: v_taluka_stats; Type: VIEW; Schema: public; Owner: goacreator
--

CREATE VIEW public.v_taluka_stats AS
 WITH taluka_creators AS (
         SELECT l.taluka,
            l.district,
            (count(c.creator_id))::integer AS creator_count
           FROM (public.locations l
             LEFT JOIN public.creators c ON ((l.location_id = c.location_id)))
          GROUP BY l.taluka, l.district
        ), taluka_businesses AS (
         SELECT l.taluka,
            (count(b.business_id))::integer AS business_count
           FROM (public.locations l
             LEFT JOIN public.businesses b ON ((l.location_id = b.location_id)))
          GROUP BY l.taluka
        ), taluka_deals AS (
         SELECT l.taluka,
            round(avg(req.offered_amount), 2) AS avg_offered_amount
           FROM ((public.locations l
             JOIN public.businesses b ON ((l.location_id = b.location_id)))
             JOIN public.collaboration_requests req ON ((b.business_id = req.business_id)))
          GROUP BY l.taluka
        ), taluka_cat_counts AS (
         SELECT l.taluka,
            cat.category_name,
            (count(*))::integer AS cat_count,
            row_number() OVER (PARTITION BY l.taluka ORDER BY (count(*)) DESC, cat.category_name) AS rn
           FROM (((public.locations l
             JOIN public.creators cr ON ((l.location_id = cr.location_id)))
             JOIN public.creator_categories cc ON ((cr.creator_id = cc.creator_id)))
             JOIN public.categories cat ON ((cc.category_id = cat.category_id)))
          GROUP BY l.taluka, cat.category_name
        )
 SELECT tc.taluka,
    tc.district,
    COALESCE(tc.creator_count, 0) AS creator_count,
    COALESCE(tb.business_count, 0) AS business_count,
    COALESCE(td.avg_offered_amount, (0)::numeric) AS avg_offered_amount,
    tcc.category_name AS top_category
   FROM (((taluka_creators tc
     LEFT JOIN taluka_businesses tb ON ((tc.taluka = tb.taluka)))
     LEFT JOIN taluka_deals td ON ((tc.taluka = td.taluka)))
     LEFT JOIN taluka_cat_counts tcc ON (((tc.taluka = tcc.taluka) AND (tcc.rn = 1))))
  ORDER BY tc.district, tc.taluka;


ALTER VIEW public.v_taluka_stats OWNER TO goacreator;

--
-- Name: v_top_businesses; Type: VIEW; Schema: public; Owner: goacreator
--

CREATE VIEW public.v_top_businesses AS
 SELECT b.business_id,
    b.user_id,
    b.business_name,
    b.industry,
    (count(
        CASE
            WHEN (req.status = 'completed'::text) THEN 1
            ELSE NULL::integer
        END))::integer AS completed_deals,
    COALESCE(sum(
        CASE
            WHEN ((req.status = 'completed'::text) AND (req.collab_type = ANY (ARRAY['paid'::text, 'hybrid'::text]))) THEN req.offered_amount
            ELSE 0
        END), (0)::bigint) AS total_spent,
    round(avg(r.rating), 2) AS avg_rating,
    (count(DISTINCT r.review_id))::integer AS review_count
   FROM ((public.businesses b
     LEFT JOIN public.collaboration_requests req ON ((b.business_id = req.business_id)))
     LEFT JOIN public.reviews r ON ((b.user_id = r.reviewee_id)))
  GROUP BY b.business_id, b.user_id, b.business_name, b.industry
  ORDER BY ((count(
        CASE
            WHEN (req.status = 'completed'::text) THEN 1
            ELSE NULL::integer
        END))::integer) DESC, COALESCE(sum(
        CASE
            WHEN ((req.status = 'completed'::text) AND (req.collab_type = ANY (ARRAY['paid'::text, 'hybrid'::text]))) THEN req.offered_amount
            ELSE 0
        END), (0)::bigint) DESC, (round(avg(r.rating), 2)) DESC NULLS LAST;


ALTER VIEW public.v_top_businesses OWNER TO goacreator;

--
-- Name: v_top_creators; Type: VIEW; Schema: public; Owner: goacreator
--

CREATE VIEW public.v_top_creators AS
 SELECT c.creator_id,
    c.user_id,
    c.full_name,
    (count(
        CASE
            WHEN (req.status = 'completed'::text) THEN 1
            ELSE NULL::integer
        END))::integer AS completed_deals,
    COALESCE(sum(
        CASE
            WHEN ((req.status = 'completed'::text) AND (req.collab_type = ANY (ARRAY['paid'::text, 'hybrid'::text]))) THEN req.offered_amount
            ELSE 0
        END), (0)::bigint) AS total_earned,
    round(avg(r.rating), 2) AS avg_rating,
    (count(DISTINCT r.review_id))::integer AS review_count
   FROM ((public.creators c
     LEFT JOIN public.collaboration_requests req ON ((c.creator_id = req.creator_id)))
     LEFT JOIN public.reviews r ON ((c.user_id = r.reviewee_id)))
  GROUP BY c.creator_id, c.user_id, c.full_name
  ORDER BY ((count(
        CASE
            WHEN (req.status = 'completed'::text) THEN 1
            ELSE NULL::integer
        END))::integer) DESC, COALESCE(sum(
        CASE
            WHEN ((req.status = 'completed'::text) AND (req.collab_type = ANY (ARRAY['paid'::text, 'hybrid'::text]))) THEN req.offered_amount
            ELSE 0
        END), (0)::bigint) DESC, (round(avg(r.rating), 2)) DESC NULLS LAST;


ALTER VIEW public.v_top_creators OWNER TO goacreator;

